    for(e = rfbClientExtensions; !handled && e; e = e->next)
      if(e->handleMessage && e->handleMessage(client, &msg))
        handled = TRUE;

    if(!handled) {
      char buffer[256];
      rfbClientLog("Unknown message type %d from VNC server\n", msg.type);
      ReadFromRFBServer(client, buffer, 256);
      return FALSE;
    }
  }
```

